async function contextFor(base,{width=1280,motion='reduce',phase='after',dnsMode='normal'}={}){const context=await browser.newContext({viewport:{width,height:900},reducedMotion:motion});const control={addressMode:'synthetic',dnsMode,requests:[]};context.on('page',p=>p.on('pageerror',e=>report.errors.push({phase,error:String(e)})));await context.route('**/*',async route=>{const req=route.request(),u=new URL(req.url());if(u.origin===base&&u.pathname==='/api/address/search'){const body=req.postDataJSON();control.requests.push({query:body.query,page:body.page,synthetic:true});report.network.push({kind:'JUSO_SYNTHETIC',phase,page:body.page});const response=syntheticAddressResult(body.query,body.page,control.addressMode);return route.fulfill({status:response.status==='UNAVAILABLE'?503:200,contentType:'application/json',body:JSON.stringify(response)});}if(u.origin===base)return route.continue();if(['cloudflare-dns.com','dns.google'].includes(u.hostname)){const name=u.searchParams.get('name'),type=u.searchParams.get('type');assert.ok(name&&!name.includes('@'));report.network.push({kind:'DNS_SYNTHETIC',phase,domain:name,type,resolver:u.hostname});if(control.dnsMode==='failure')return route.abort('failed');return route.fulfill({status:200,contentType:'application/dns-json',headers:{'access-control-allow-origin':'*'},body:JSON.stringify(emailDns(name,type,control.dnsMode,u.hostname))});}report.errors.push({phase,kind:'UNEXPECTED_EXTERNAL',url:u.origin+u.pathname});return route.abort();});return {context,control};}
